const SCREENS: Record<ScreenId, { Screen: (props: ScreenProps) => ReactNode; width: number; height: number; dir: "ltr" | "rtl" }> = {
  mapFirst: { Screen: MapFirst, width: 390, height: 844, dir: "ltr" },
  timeline: { Screen: Timeline, width: 390, height: 844, dir: "ltr" },
  compact: { Screen: Compact, width: 390, height: 844, dir: "ltr" },
};

/*
 * How screens come and go, as UIKit's navigation does it (React Navigation's forHorizontalIOS): the
 * new screen slides in over the old one, which moves back under a dim; Back reverses it. A sheet link
 * covers the screen from below (forVerticalIOS); dissolve fades the new screen in as the old one
 * darkens, as UIKit's cross-dissolve does (forCrossDissolveIOS).
 * Smart: the new screen comes in on top, where the layers they share morph and the rest fades in.
 * What doesn't move stays under the new screen, as it is, until that has settled.
 */

/** forHorizontalIOS: the screen under a pushed one moves a third of the way back (%), under a 10% dim. */
const UNDER = { shift: -30, dim: 0.1 };
const dimmed = (by: number) => "brightness(" + (1 - by) + ")";

const screenVariants: Variants = {
  enter: (v?: Via) => {
    const s = v?.dir === "rtl" ? -1 : 1;
    switch (v?.kind) {
      case "push":
        return v.back ? { x: UNDER.shift * s + "%", filter: dimmed(UNDER.dim), zIndex: 0 } : { x: 100 * s + "%", zIndex: 1 };
      case "sheet":
        return v.back ? { zIndex: 0 } : { y: "100%", zIndex: 1 };
      case "dissolve":
        return v.back ? { filter: "brightness(0)", zIndex: 0 } : { opacity: 0, zIndex: 1 };
      default:
        return { zIndex: 0 };
    }
  },
  smart: { zIndex: 1 },
  center: (v?: Via) => ({ x: 0, y: 0, opacity: 1, filter: "brightness(1)", transition: v?.transition ?? (v?.kind === "smart" ? MOTION.morph : MOTION.page), transitionEnd: { filter: "none" } }),
  exit: (v?: Via) => {
    const s = v?.dir === "rtl" ? -1 : 1;
    const transition = { ...(v?.transition ?? MOTION.page), zIndex: { duration: 0 } };
    const stay = { opacity: 0, zIndex: 0, transition: { ...transition, opacity: { duration: 0, delay: settled(v) } } };
    switch (v?.kind) {
      case "push":
        return v.back ? { x: 100 * s + "%", zIndex: 1, transition } : { x: UNDER.shift * s + "%", filter: dimmed(UNDER.dim), zIndex: 0, transition };
      case "sheet":
        return v.back ? { y: "100%", zIndex: 1, transition } : stay;
      case "dissolve":
        return v.back ? { opacity: 0, zIndex: 1, transition } : { filter: "brightness(0)", zIndex: 0, transition };
      default:
        return stay;
    }
  },
};

/** With Reduce Motion on, pages cross-fade instead of moving, as iOS does (Prefer Cross-Fade Transitions). */
const calm = (v: Via | undefined, reduced: boolean): Via | undefined => (reduced && v && v.kind !== "smart" && !v.transition ? { ...v, kind: "dissolve" } : v);

/**
 * Swiping back, as UIKit's navigation does it (React Navigation's Card, with its gesture defaults): a
 * drag that starts within 50px of the leading edge takes hold once it has gone 5px along, unless it
 * went 20px up or down first. The screen on top follows the finger and the one before it shows
 * underneath, coming from −30% as its dim lifts (forHorizontalIOS, by how far the top one has gone).
 * Let go, it closes when where it is plus 0.3s at the speed it left with is past half the width,
 * else springs back: either way on the navigation spring, carrying that speed. A screen swipes back
 * when it was pushed and has come in, with nothing open over it.
 */
const SWIPE = { edge: 50, start: 5, slack: 20, impact: 0.3 };

/**
 * The swipe on a device `width` wide, toward the trailing edge of the screen it goes back to (`rtl`):
 * `can` says whether it may start now, `pop` goes back once it has closed. While `on`, the screen
 * on top moves by `x` and the one under it by `under`, dimmed by `dim`.
 */
function useSwipeBack(width: number, rtl: boolean, can: () => boolean, pop: () => void) {
  // How far the finger has pulled the screen on top, in px: what the spring finishes, carrying its speed.
  const pull = useMotionValue(0);
  const [on, setOn] = useState(false);
  // Its width and way, kept from when it takes hold: the screen it goes back to has its own, and moves nothing still leaving.
  const way = useRef({ width, s: 1 });
  // How much of the way it has gone, kept between rest and gone as React Navigation's interpolation is.
  const gone = useTransform(() => Math.min(1, Math.max(0, pull.get() / way.current.width)));
  const x = useTransform(() => gone.get() * 100 * way.current.s + "%");
  const under = useTransform(() => UNDER.shift * (1 - gone.get()) * way.current.s + "%");
  const dim = useTransform(() => dimmed(UNDER.dim * (1 - gone.get())));
  const onPointerDown = (e: ReactPointerEvent<HTMLElement>) => {
    if (e.button !== 0 || on || !can()) return;
    const s = rtl ? -1 : 1;
    const el = e.currentTarget;
    const r = el.getBoundingClientRect();
    // The stage may show the device smaller (CSS zoom): the pointer moves in its pixels, the screen in the device's.
    const zoom = r.width / el.offsetWidth || 1;
    if ((rtl ? r.right - e.clientX : e.clientX - r.left) / zoom > SWIPE.edge) return;
    const from = { x: e.clientX, y: e.clientY };
    let held = false;
    const swallow = (c: Event) => {
      c.stopPropagation();
      c.preventDefault();
    };
    const move = (m: PointerEvent) => {
      const along = ((m.clientX - from.x) / zoom) * s;
      if (!held) {
        // Up or down first, it isn't a swipe; along, it takes hold.
        if (Math.abs(m.clientY - from.y) / zoom > SWIPE.slack) return stop();
        if (along < SWIPE.start) return;
        held = true;
        unpress?.();
        getSelection()?.removeAllRanges();
        window.addEventListener("click", swallow, true);
        way.current = { width, s };
        pull.jump(along);
        setOn(true);
      }
      pull.set(along);
    };
    const stop = () => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
      window.removeEventListener("pointercancel", up);
      window.removeEventListener("dragstart", swallow, true);
    };
    const up = (u: PointerEvent) => {
      stop();
      if (!held) return;
      setTimeout(() => window.removeEventListener("click", swallow, true), 0);
      const speed = pull.getVelocity();
      const closes = u.type === "pointerup" && pull.get() + SWIPE.impact * speed > width / 2;
      void animate(pull, closes ? width : 0, { ...MOTION.page, velocity: speed }).then(() => {
        if (closes) pop();
        setOn(false);
      });
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
    window.addEventListener("pointercancel", up);
    // Dragging from the edge doesn't drag a picture away.
    window.addEventListener("dragstart", swallow, true);
  };
  return { on, x, under, dim, onPointerDown };
}

/** While a swipe holds the screens (and until it has finished), they take no taps and select no text. */
const SWIPING: CSSProperties = { pointerEvents: "none", userSelect: "none" };

interface Nav {
  /** Bumps on every move, so each visit is its own element that can enter and leave. */
  visit: number;
  screen: ScreenId;
  /** How it was gone to, the last time it was (not by going back): a pushed screen pops the way it came. */
  came?: Via["kind"];
  /** The screens before it, and how each was gone to. */
  history: { screen: ScreenId; came?: Via["kind"] }[];
  via?: Via;
  /** Shared layers match within a group: smart transitions stay in it, other kinds start a new one. */
  group: number;
}

/** Go to another screen, or back to the one before. */
function move(n: Nav, to: ScreenId | "back", via: Via): Nav {
  const back = to === "back";
  const prev = n.history[n.history.length - 1];
  if (back && !prev) return n;
  const screen = back ? prev.screen : to;
  return {
    visit: n.visit + 1,
    screen,
    came: back ? prev.came : via.kind,
    history: back ? n.history.slice(0, -1) : [...n.history, { screen: n.screen, came: n.came }],
    via: { ...via, back, dir: SCREENS[screen].dir },
    group: via.kind === "smart" ? n.group : n.group + 1,
  };
}

/** Back by a swipe: the platform's pop. */
const BACK: Via = { kind: "push" };

const VISIT: CSSProperties = { position: "absolute", inset: 0, overflowX: "hidden", overflowY: "auto" };

export default function Prototype({ start = "compact" }: { start?: ScreenId }) {
  const [nav, setNav] = useState<Nav>({ visit: 0, screen: start, history: [], group: 0 });
  const reduced = useReducedMotion() ?? false;
  const go = useCallback((to: ScreenId | "back", via: Via) => setNav((n) => move(n, to, via)), []);
  // As in UIKit, a screen swipes back once it has come in.
  const arrived = useRef(nav.visit);
  const { Screen, width, height } = SCREENS[nav.screen];
  const via = calm(nav.via, reduced);
  // Swiping back: while the screen is pulled away, the one before shows under it as it was left, and becomes the screen once the swipe closes.
  const back = nav.history.length ? move(nav, "back", BACK) : null;
  const swipe = useSwipeBack(
    width,
    !!back && SCREENS[back.screen].dir === "rtl",
    () => !!back && nav.came === "push" && arrived.current === nav.visit,
    () => setNav((n) => (n.visit === nav.visit ? move(n, "back", BACK) : n)),
  );
  const under = swipe.on ? back : null;
  const Under = under ? SCREENS[under.screen].Screen : null;
  return (
    <div onPointerDown={swipe.onPointerDown} style={{ position: "relative", width, height, overflow: "hidden", isolation: "isolate", ...(swipe.on ? SWIPING : {}) }}>
      <style>{qalamCSS}</style>
      <MotionConfig transition={via?.transition ?? MOTION.morph} reducedMotion="user">
        <AnimatePresence initial={false} custom={via}>
          {under && Under && (
            <motion.div key={under.visit} initial={false} layoutScroll style={{ ...VISIT, x: swipe.under, filter: swipe.dim }}>
              <LayoutGroup id={`flow-${under.group}`}>
                <Under go={go} via={under.via} />
              </LayoutGroup>
            </motion.div>
          )}
          <motion.div
            key={nav.visit}
            custom={via}
            variants={screenVariants}
            initial={via?.kind === "smart" ? "smart" : "enter"}
            animate="center"
            exit="exit"
            layoutScroll
            onAnimationComplete={(d) => {
              if (d === "center") arrived.current = nav.visit;
            }}
            style={{ ...VISIT, ...(swipe.on ? { x: swipe.x } : {}) }}
          >
            <LayoutGroup id={`flow-${nav.group}`}>
              <Screen go={go} via={nav.via} />
            </LayoutGroup>
          </motion.div>
        </AnimatePresence>
      </MotionConfig>
    </div>
  );
}
